const rows=$input.all().map(i=>i.json).filter(r=>r&&r.ID_Lead&&String(r.Estado)==='llamar_manual');
if(!rows.length) return [];
rows.sort((a,b)=>(Number(b.Pre_Score)||0)-(Number(a.Pre_Score)||0));
const CAP=10;
const sel=rows.slice(0,CAP);
const system="<identidad>Eres coach de ventas senior de ACCES GROUP (ciberseguridad, GRC, TI). Preparas a Ricardo Varela para LLAMADAS telefonicas a prospectos calificados. Espanol de negocio mexicano, calido, consultivo, cero jerga tecnica, cero presion. Regla 70/30: escuchar mas que hablar.</identidad><portafolio>ACCES GROUP: Consulting (gobierno de TI, riesgo, ISO 27001/22301, BIA/BCP/DRP), Audit (auditoria de sistemas, ciberseguridad, NIST), Solutions (nube hibrida, redes criticas, continuidad, SASE), IT (SOC/NOC/CISO 24x7, pentesting, analisis de vulnerabilidades, Red/Blue Team, phishing), Training. NO hacemos temas fisicos/mecanicos (fugas, hermeticidad, calibracion): TODO se enmarca en seguridad de la informacion y sistemas.</portafolio><encuadre>ICP-1 (gasolineras, Anexo 21 SAT): el angulo es la EVIDENCIA TECNICA de los sistemas de control volumetrico y de informacion (integridad de datos, controles de acceso, analisis de vulnerabilidades en los sistemas), NUNCA deteccion fisica de fugas ni hermeticidad. ICP-2 (financiero regulado): evidencia auditable para CNBV (pentest con reporte). ICP-3 (manufactura/exportador): controles demostrables ante auditorias de clientes globales.</encuadre><objetivo>El UNICO objetivo de la llamada es conseguir una REUNION de 20 minutos. No se vende el proyecto por telefono; se vende el siguiente paso pequeno.</objetivo><tarea>Para CADA cuenta te doy Empresa, Sector, Micro-ICP, Gancho y Ciudad. Genera un mini-guion de llamada REAL, que Ricardo pueda decir tal cual.</tarea><reglas>Frases cortas y naturales. Nada de miedo regulatorio, nada de cumplimiento garantizado, NO inventes datos internos de la empresa. El cierre pide la reunion SIN proponer fecha/hora exacta (ofrece mandar un par de horarios o tu liga).</reglas><salida>Devuelve SOLO un JSON array (sin backticks), un objeto por cuenta EN EL MISMO ORDEN recibido: [{\"empresa\":\"\",\"con_quien\":\"a quien pedir cuando contesten (rol probable: dueno, gerente, encargado de sistemas/administracion)\",\"apertura\":\"1-2 frases para abrir con permiso y presentarte\",\"gancho_valor\":\"el dolor relevante del sector que ACCES resuelve, en lenguaje de negocio (1-2 frases)\",\"preguntas\":[\"pregunta 1 de diagnostico para engancharlo\",\"pregunta 2\"],\"objecion\":\"la objecion tipica que van a poner -> como responderla en 1 frase\",\"cierre\":\"como pedir la reunion de 20 min sin proponer hora exacta\"}]</salida>";
const lista=sel.map((r,i)=>`${i+1}. Empresa: ${r.Empresa} | Sector: ${r.Sector||''} | Micro-ICP: ${r.Micro_ICP||''} | Gancho: ${r.Gancho||r.Trigger_Regulatorio||''} | Ciudad: ${[r.Ciudad,r.Estado_Region].filter(Boolean).join(', ')}`).join('\n');
const user=`Cuentas para llamar hoy (genera un guion por cada una, EN ESTE ORDEN):\n${lista}\n\nDevuelve SOLO el JSON array.`;
return [{json:{system,user,_leads:sel,_total:rows.length,_cap:CAP}}];

const L='https://raw.githubusercontent.com/sanrotech369-dot/acces-assets/main/';
const hoy=$now.toFormat('yyyy-LL-dd');
const prep=$('Prep guiones').first().json;
const leads=(prep&&prep._leads)||[];
if(!leads.length) return [];
let arr=[];
try{const b=$json.content||[];const t=b.find(x=>x&&x.type==='text');let txt=(t?t.text:'[]').replace(/^```json/i,'').replace(/```$/,'').trim();arr=JSON.parse(txt);}catch(e){arr=[];}
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const sec=(icon,titulo,cont)=>'<p style="margin:8px 0 2px 0;font-size:12px;color:#0a3d62;font-weight:bold;">'+icon+' '+titulo+'</p><p style="margin:0 0 6px 0;color:#333;">'+cont+'</p>';
const cards=leads.map((r,i)=>{
  const g=arr[i]||{};
  const tel=esc(r.Telefono||'-');
  const ciu=esc([r.Ciudad,r.Estado_Region].filter(Boolean).join(', ')||'-');
  const preg=Array.isArray(g.preguntas)?g.preguntas.filter(Boolean):[];
  const pregHtml=preg.length?('<ul style="margin:0 0 6px 18px;padding:0;color:#333;">'+preg.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>'):'';
  const cuerpo = (g.con_quien||g.apertura)
   ? (sec('&#128100;','Con qui&eacute;n hablar', esc(g.con_quien||'Pregunta por el dueno o encargado de administracion/sistemas.'))
     + sec('&#127916;','Apertura', esc(g.apertura||''))
     + sec('&#128161;','Gancho de valor (lo que ACCES resuelve)', esc(g.gancho_valor||r.Gancho||''))
     + (pregHtml?('<p style="margin:8px 0 2px 0;font-size:12px;color:#0a3d62;font-weight:bold;">&#10067; Preguntas para enganchar</p>'+pregHtml):'')
     + sec('&#128737;&#65039;','Si te ponen objeci&oacute;n', esc(g.objecion||''))
     + sec('&#9989;','Cierre a reuni&oacute;n', esc(g.cierre||'Pide una reunion breve de 20 min y ofrece mandar un par de horarios.')))
   : ('<p style="margin:6px 0;color:#a00;">(Gu&iacute;on no disponible &mdash; usa el gancho base: '+esc(r.Gancho||'')+')</p>');
  return '<div style="border:1px solid #e3e8ee;border-left:4px solid #0a3d62;border-radius:6px;padding:14px 16px;margin:0 0 16px 0;">'
    +'<div style="display:flex;justify-content:space-between;flex-wrap:wrap;">'
    +'<div><span style="font-size:16px;font-weight:bold;color:#0a3d62;">'+(i+1)+'. '+esc(r.Empresa)+'</span><br><span style="color:#888;font-size:12px;">'+esc(r.Sector||'')+' &middot; '+ciu+'</span></div>'
    +'<div style="text-align:right;"><span style="color:#888;font-size:11px;">TEL&Eacute;FONO</span><br><span style="font-size:17px;color:#0a3d62;font-weight:bold;">'+tel+'</span></div>'
    +'</div><hr style="border:none;border-top:1px solid #eee;margin:10px 0;">'+cuerpo+'</div>';
}).join('');
const extra=(prep._total>prep._cap)?('<p style="color:#888;font-size:12px;">(+'+(prep._total-prep._cap)+' cuenta(s) mas en cola; apareceran manana.)</p>'):'';
const html='<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:840px;">'
  +'<p style="margin:0 0 14px 0;"><img src="'+L+'logo.png" alt="ACCES GROUP" style="max-width:200px;height:auto;"></p>'
  +'<h2 style="margin:0 0 4px 0;color:#0a3d62;">&#128222; Tus llamadas de hoy &mdash; con gui&oacute;n listo</h2>'
  +'<p style="margin:0 0 16px 0;color:#666;">ATENEA prepar&oacute; <strong>'+leads.length+'</strong> llamada(s). Cada tarjeta trae con qui&eacute;n hablar, c&oacute;mo abrir, el gancho de valor y c&oacute;mo cerrar la reuni&oacute;n de 20 min. &iexcl;A marcar!</p>'
  +cards+extra
  +'<p style="margin:18px 0 0 0;color:#888;font-size:12px;">Cuando agendes o descartes una, cambia su Estado en el CRM y se cae sola de esta lista. &mdash; ATENEA &middot; ACCES GROUP</p>'
  +'</div>';
return [{json:{reporte_html:html,total:leads.length,hoy}}];
